def solve():
    n = int(input())
    a = list(map(int, input().split()))

    max_val = max(a)
    min_val = min(a)

    if max_val == min_val:
        print(0)
    else:
        count_max = a.count(max_val)
        count_min = a.count(min_val)

        if count_max == 1 and count_min == 1:
            print(max_val - min_val)
        else:
            print(max(max_val - min_val, max_val - min(a[i] for i in range(n) if a[i] != min_val),
                          max(a[i] for i in range(n) if a[i] != max_val) - min_val))

if __name__ == "__main__":
    solve()

def min_instability(n, a):
    a.sort()
    if n == 2:
        return 0
    return min(a[-1] - a[2], a[-2] - a[1])

n = int(input())
a = list(map(int, input().split()))
print(min_instability(n, a))
